// Package arithmetic provides small numeric helpers used by the application.
package arithmetic

// Add returns the sum of a and b.
func Add(a, b int) int {
	return a + b
}

package main

import "example.com/bench/arithmetic"

func add(a, b int) int {
	return arithmetic.Add(a, b)
}

func main() {}

package arithmetic

import "testing"

func TestAdd(t *testing.T) {
	tests := []struct {
		name string
		a    int
		b    int
		want int
	}{
		{name: "positive", a: 2, b: 3, want: 5},
		{name: "negative", a: -2, b: -3, want: -5},
		{name: "zero", a: 0, b: 0, want: 0},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := Add(tt.a, tt.b); got != tt.want {
				t.Fatalf("Add(%d, %d) = %d, want %d", tt.a, tt.b, got, tt.want)
			}
		})
	}
}

